import{_ as t,d as i,e as a,y as n}from"./chunks/framework.D7CAgLCq.js";const p=JSON.parse('{"title":"Mars Climate Orbiter: a unit mismatch at an interface","description":"Distinguish sufficient information, the specified units, actual execution, and the reported causes.","frontmatter":{"title":"Mars Climate Orbiter: a unit mismatch at an interface","description":"Distinguish sufficient information, the specified units, actual execution, and the reported causes.","kind":"Documented case","source_type":"Official accident investigation"},"headers":[],"relativePath":"en/cases/mars-climate-orbiter.md","filePath":"en/cases/mars-climate-orbiter.md"}'),r={name:"en/cases/mars-climate-orbiter.md"};function s(o,e,c,h,d,l){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="mars-climate-orbiter-a-unit-mismatch-at-an-interface" tabindex="-1">Mars Climate Orbiter: a unit mismatch at an interface <a class="header-anchor" href="#mars-climate-orbiter-a-unit-mismatch-at-an-interface" aria-label="Permalink to &quot;Mars Climate Orbiter: a unit mismatch at an interface&quot;">​</a></h1><p>Mars Climate Orbiter was lost on arrival at Mars in September 1999. NASA’s mission record identifies a navigation error involving a unit conversion. The investigation gives a more specific account of what failed and which organizational checks did not catch it.</p><h2 id="what-the-investigation-records" tabindex="-1">What the investigation records <a class="header-anchor" href="#what-the-investigation-records" aria-label="Permalink to &quot;What the investigation records&quot;">​</a></h2><p>The ground software SM_FORCES produced thruster-impulse data in pound-force seconds, although the interface specification required newton seconds. Navigation processing interpreted the values using the specified units, underestimating the relevant force effect by a factor of about 4.45. The report also lists verification, communication, staffing, and training issues as contributing factors. See the <a href="https://llis.nasa.gov/llis_lib/pdf/1009464main1_0641-mr.pdf" target="_blank" rel="noreferrer">Phase I report</a>, printed pages 6–7 and 16–17.</p><p>The specification already contained the unit requirement. A correct document therefore coexisted with nonconforming output. Data anomalies were noticed in April; the unit mismatch was identified on September 29, six days after the loss. Navigation estimates were then recomputed using corrected values (pages 13–14, 16, and 18).</p><p>The report’s wording on verification is qualified. End-to-end testing of the small-forces ground software “did not appear to be accomplished”; whether independent verification and validation had been completed “was not clear.” These statements should not be strengthened into a definite claim that no such testing ever occurred (pages 7, 15, and 25).</p><h2 id="read-the-interface-without-merging-the-questions" tabindex="-1">Read the interface without merging the questions <a class="header-anchor" href="#read-the-interface-without-merging-the-questions" aria-label="Permalink to &quot;Read the interface without merging the questions&quot;">​</a></h2><p><a href="/xi-kari-skill/handbook/en/theory/appendix-c.html#section-c-7">C.7</a> separates representational sufficiency from correct actual execution. In the book’s finite example, a representation can merge states requiring different answers; no new decoder can recover a distinction already lost. The Orbiter mismatch differs: distinct impulses remained distinct numbers, and knowing the actual units permitted conversion.</p><p>Reading the accident as a failure to implement or use the intended unit mapping is this site’s interpretation. NASA’s report supplies the accident findings; it does not use the framework’s classification. The theory also does not require every real failure to have a uniquely identifiable category when inputs or rules are unknown.</p><p>Receiving a file establishes transmission, not correct interpretation. Likewise, identifying a faulty interface does not settle all responsibility. Production, use, validation, supervision, and authority each require their own evidence. The person most visible at the last step is not automatically responsible for every contributing condition.</p><h2 id="what-this-case-does-not-establish" tabindex="-1">What this case does not establish <a class="header-anchor" href="#what-this-case-does-not-establish" aria-label="Permalink to &quot;What this case does not establish&quot;">​</a></h2><p>It is not an empirical version of <a href="/xi-kari-skill/handbook/en/theory/part-02.html#section-2-4-2">§2.4.2’s two-type causal counterexample</a>: the report does not estimate two average causal effects and multiply them. <a href="/xi-kari-skill/handbook/en/theory/appendix-c.html#section-c-12">C.12</a> distinguishes representation composition from causal-chain composition and joint feasibility.</p><p>Nor does explaining a known accident establish that this framework would have predicted it beforehand. The case supports a narrower reading question: what information crossed the interface, with which units and rules, and what was actually checked?</p><h2 id="sources-and-further-reading" tabindex="-1">Sources and further reading <a class="header-anchor" href="#sources-and-further-reading" aria-label="Permalink to &quot;Sources and further reading&quot;">​</a></h2><ul><li>NASA, <a href="https://llis.nasa.gov/llis_lib/pdf/1009464main1_0641-mr.pdf" target="_blank" rel="noreferrer">Mars Climate Orbiter Mishap Investigation Board, Phase I Report</a>, November 10, 1999; page locators above.</li><li>NASA, <a href="https://science.nasa.gov/mission/mars-climate-orbiter/" target="_blank" rel="noreferrer">Mars Climate Orbiter mission record</a>.</li><li><a href="./../concepts/representation.html">Representation</a>, <a href="./../concepts/chain.html">causal chains</a>, and <a href="./../concepts/responsibility.html">responsibility</a>.</li></ul><p>This English account follows the sources and factual scope of the existing Chinese case page; it adds no new investigation findings.</p>',16)])])}const f=t(r,[["render",s]]);export{p as __pageData,f as default};
